    def find_min_spanning_tree(n: int, m: int, roads: list) -> list:
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                if rank[rootX] > rank[rootY]:
                    parent[rootY] = rootX
                elif rank[rootX] < rank[rootY]:
                    parent[rootX] = rootY
                else:
                    parent[rootY] = rootX
                    rank[rootX] += 1

        sorted_roads = sorted(roads, key=lambda x: x[2])
        mst = []
        for u, v, w in sorted_roads:
            if find(u) != find(v):
                union(u, v)
                mst.append((u, v, w))
        return mst

    def bfs(start, end, graph):
        from collections import deque
        queue = deque([start])
        visited = set([start])
        distance = {start: 0}
        while queue:
            node = queue.popleft()
            if node == end:
                return distance[node]
            for neighbor, weight in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
                    distance[neighbor] = distance[node] + weight
        return float('inf')

    graph = [[] for _ in range(n + 1)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    mst = find_min_spanning_tree(n, m, roads)
    mst_edges = set((min(u, v), max(u, v), w) for u, v, w in mst)
    result = float('inf')
    for u, v, w in roads:
        if (min(u, v), max(u, v), w) not in mst_edges:
            graph[u].remove((v, w))
            graph[v].remove((u, w))
            result = min(result, bfs(1, p, graph))
            graph[u].append((v, w))
            graph[v].append((u, w))
    return result if result != float('inf') else 0
